import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Alireza Beiranvand', position: 'GK', age: 33, club: 'Tractor', bio: {"es":"Ha pasado casi una década desde que Beiranvand se estableció como el portero titular de Irán y ganó gran popularidad después de detener el penalti de Cristiano Ronaldo en la Copa del Mundo de 2018. En los últimos años, sin embargo, se ha visto rodeado de polémica por algunas declaraciones insólitas y su salida de Persépolis. Sus actuaciones con la selección nacional han disminuido desde que se mudó a Tractor, lo que llevó a algunos críticos a pedir su eliminación de la alineación titular de Irán. Su famosa parada de penalti contra Ronaldo se ha arraigado tanto en la cultura popular que ha sido recreada en los últimos años en dos series de televisión iraníes, The Rebel y The Savage, como parte de sus historias. Además, tras sus destacadas actuaciones en Rusia 2018, se produjo una película basada en la turbulenta historia de su vida; otra buena actuación este verano podría inspirar una secuela.","en":"It has been nearly a decade since Beiranvand established himself as Iran’s first-choice goalkeeper and he gained widespread popularity after stopping Cristiano Ronaldo's penalty at the 2018 World Cup. In recent years, however, he has been surrounded by controversy owing to some unusual statements and his departure from Persepolis. His performances for the national team have declined since his move to Tractor, leading some critics to call for his removal from Iran’s starting lineup. His famous penalty save against Ronaldo has become so ingrained in popular culture that it has been recreated in recent years in two Iranian TV series, The Rebel and The Savage, as part of their storylines. In addition, following his standout performances at Russia 2018, a film based on his turbulent life story was produced – another strong showing this summer could inspire a sequel."}, special: "No 1 goalkeeper" },
  { number: 12, name: 'Payam Niazmand', position: 'GK', age: 31, club: 'Persepolis', bio: {"es":"El cuarto portero de Irán en la Copa del Mundo de 2022 (Irán fue el único equipo que eligió a cuatro porteros) ha cerrado la brecha con Alireza Beiranvand hasta tal punto que ahora un solo desliz del hombre del Tractor podría convertir a Niazmand en el número uno de Irán. Estuve en el último Mundial, pero no tuve la oportunidad de jugar. Esta vez estoy mucho más motivado y espero tener minutos en el campo”. Esta temporada, bajo la dirección de Emilio Álvarez, ex entrenador de porteros del Manchester United de David de Gea, ha mostrado una mejora significativa. Sin embargo, lo que hasta ahora ha impedido que Niazmand se convierta en el portero titular de Irán es una pérdida de confianza durante los partidos internacionales. ¿Podría ser diferente este año?","en":"Iran’s fourth-choice goalkeeper at the 2022 World Cup (Iran were the only team to take four keepers) has closed the gap to Alireza Beiranvand to such an extent that now just a single slip from the Tractor man could see Niazmand become Iran’s No 1. Having joined Persepolis at the start of the 2025–26 season, Niazmand said in his first interview: “The greatest dream of any goalkeeper is to play in the World Cup. I was at the last World Cup, but I didn’t get the chance to play. This time, I’m far more motivated, and I hope to get minutes on the pitch.” This season, under the guidance of Emilio Álvarez – David de Gea’s former Manchester United goalkeeping coach – he has shown significant improvement. However, what has so far prevented Niazmand from becoming Iran’s first-choice goalkeeper is a drop in confidence during international matches. Could it be different this year?"} },
  { number: 22, name: 'Seyed Hossein Hosseini', position: 'GK', age: 33, club: 'Sepahan', bio: {"es":"\"Lo había visualizado de antemano y estaba muy feliz de jugar en la Copa del Mundo. Había trabajado muy duro y estaba contento de haber logrado mi objetivo\", dijo Hosseini sobre jugar contra Inglaterra en la Copa del Mundo 2022. Pero la lección más importante que aprendió de ese partido fue lo rápido que un sueño puede convertirse en una pesadilla: después de sustituir al lesionado Alireza Beiranvand, su aparición de 70 minutos terminó encajando seis goles, mientras Irán sufría su derrota más abultada en su historia de la Copa del Mundo. Hosseini también jugó los 90 minutos completos en el segundo partido contra Gales, manteniendo la portería a cero, pero ahora ha caído a la tercera opción. Aun así, no le falta confianza: \"He sido el portero más en forma de Irán en los últimos años. Los demás no han sido tan excepcionales\".","en":"“I had visualized it beforehand and was very happy to be playing in the World Cup. I had worked very hard and was glad to have achieved my goal,” Hosseini said about playing against England at the 2022 World Cup. But the biggest lesson he took from that match was how quickly a dream can turn into a nightmare: after coming on for the injured Alireza Beiranvand, his 70-minute appearance ended with conceding six goals, as Iran suffered their heaviest defeat in their World Cup history. Hosseini also played the full 90 minutes in the second match against Wales – keeping a clean sheet – but has now dropped to third choice. Still, he doesn’t lack for confidence: “I’ve been the most in-form goalkeeper in Iran in recent years. The others haven’t been that exceptional.”"} },
  // Defensores
  { number: 2, name: 'Saleh Hardani', position: 'DF', age: 27, club: 'Esteghlal', bio: {"es":"Uno de los muchos tatuajes de Hardani refleja su forma de afrontar la vida: paciencia, silencio y esfuerzo. Al inicio de la actual temporada se encontraba en el banquillo del Esteghlal y parecía poco probable que pudiera conseguir un puesto en la selección nacional para el Mundial. Sin embargo, logró regresar a la alineación titular, convirtiéndose en uno de los capitanes del equipo y ganándose un lugar en el equipo de Amir Ghalenoei. A pesar de su estatura relativamente baja, Hardani posee una constitución fuerte y musculosa. Esta fuerza física le ayudó a realizar una actuación destacada contra Sadio Mané en un partido contra el Al-Nassr en la Elite de la Liga de Campeones AFC el año pasado. En marzo, mientras Hardani estaba con la selección nacional, su casa en Teherán resultó gravemente dañada en un bombardeo atribuido a Estados Unidos e Israel. En respuesta, dijo: “Que sea sacrificado por mi amado pueblo del país”.","en":"One of Hardani’s many tattoos reflects his approach to life: patience, silence and effort. At the start of the current season, he found himself on the bench at Esteghlal and it seemed unlikely he would earn a place in the national team for the World Cup. However, he fought his way back into the starting lineup, becoming one of the team captains and earning a spot in Amir Ghalenoei’s squad. Despite his relatively short stature, Hardani possesses a strong, muscular build. This physical strength helped him deliver a standout performance against Sadio Mané in a match against Al-Nassr in the AFC Champions League Elite last year. In March, while Hardani was with the national team, his home in Tehran was severely damaged in a bombing attributed to the United States and Israel. In response, he said: “May it be sacrificed for my beloved people of the country.”"} },
  { number: 3, name: 'Ehsan Hajsafi', position: 'DF', age: 36, club: 'Sepahan', bio: {"es":"Hajsafi ha aparecido en los nueve partidos de Irán en las últimas tres Copas Mundiales, pero cuando no fue convocado a la selección nacional en los últimos dos años, parecía que su carrera internacional podría haber llegado a su fin. Sin embargo, las decepcionantes actuaciones de otros contendientes en el lateral izquierdo convencieron a Amir Ghalenoei de llamarlo pocos meses antes de la Copa del Mundo, dándole a Hajsafi la oportunidad, a los 36 años, de convertirse en el primer jugador iraní en alcanzar dos dígitos de participaciones en la Copa del Mundo. Una de las razones clave detrás de la larga y exitosa carrera de Hajsafi es su estilo de vida tranquilo, disciplinado y libre de controversias. En el campo, sin embargo, es conocido por su intensidad: compara su estilo de juego con un emoji particular: \"Soy agresivo en el campo y no bromeo con nadie. Eso viene de las exigencias del juego: todos tienen que estar 100% concentrados y preparados. Puedes usar el emoji rojo enojado para describirme en los partidos, porque soy muy serio e intenso\".","en":"Hajsafi has featured in all nine of Iran’s matches across the last three World Cups, but when he was not called up to the national team over the past two years, it seemed his international career might have come to an end. However, the underwhelming performances of other contenders at left-back convinced Amir Ghalenoei to recall him just months before the World Cup, giving Hajsafi the chance aged 36 to become the first Iranian player to reach double-digit World Cup appearances. One of the key reasons behind Hajsafi’s long and successful career is his calm, disciplined, and controversy-free lifestyle. On the pitch, however, he is known for his intensity: he compares his style of play with a particular emoji: “I’m aggressive on the pitch and I don’t joke with anyone. That comes from the demands of the game – everyone has to come with 100% focus and readiness. You can use the red angry emoji to describe me in matches, because I’m very serious and intense.”"}, special: "Plays with anger" },
  { number: 4, name: 'Shoja Khalilzadeh', position: 'DF', age: 37, club: 'Tractor', bio: {"es":"Shoja –cuyo nombre en persa significa “valiente” o “valiente”– es el tipo de defensor que nunca se deja intimidar, ya sea en las batallas dentro o fuera del campo. Ha estado constantemente entre los jugadores con más tarjetas amarillas y rojas de la liga iraní. Recientemente estuvo involucrado en una disputa de alto perfil con su viejo amigo y ex compañero de equipo Hossein Kanaani-Zadegan, lo que llevó a que los dos dejaran de seguirse en Instagram. La pareja, que durante mucho tiempo había formado la columna vertebral de la defensa de Irán, intercambió burlas durante un partido Tractor vs Persépolis en la Copa Hazfi imitando las celebraciones de gol del otro. Después de ser enviado a la banca por Carlos Queiroz en Qatar 2022, se espera que Khalilzadeh sea un titular clave con Amir Ghalenoei este verano.","en":"Shoja – whose name in Persian means “brave” or “fearless” – is the kind of defender who is never intimidated, whether in on-field battles or off-field confrontations. He has consistently been among the players with the most yellow and red cards in the Iranian league. Recently he was involved in a high-profile dispute with his longtime friend and former teammate Hossein Kanaani-Zadegan, which led to the two unfollowing each other on Instagram. The pair, who had long formed the backbone of Iran’s defence, exchanged taunts during a Tractor v Persepolis match in the Hazfi Cup by mimicking each other’s goal celebrations. After being benched by Carlos Queiroz at Qatar 2022, Khalilzadeh is expected to be a key starter under Amir Ghalenoei this summer."}, special: "No-nonsense" },
  { number: 5, name: 'Milad Mohammadi', position: 'DF', age: 32, club: 'Persepolis', bio: {"es":"Después de ocho años jugando en clubes de Rusia, Bélgica, Grecia y Turquía, Mohammadi, cuyo hermano gemelo, Mehrdad, juega en Irán en el Tractor, regresó a la liga iraní en 2024 con el Persépolis. Sin embargo, jugar en el equipo de su infancia no le fue bien y, tras una década como titular en la selección, durante un tiempo perdió su lugar en la plantilla. Esa crisis coincidió con la decisión del entonces entrenador del Persépolis, el exdelantero del Bayern Munich Vahid Hashemian, de desplegarlo como lateral derecho, pero después de la partida de Hashemian, Mohammadi fue trasladado nuevamente a la izquierda, donde redescubrió su forma y con ella su lugar internacional. Mohammadi a veces puede dudar en momentos clave, pero como lateral izquierdo rápido y combativo puede ser una gran ventaja cuando está en plena forma. Con su capacidad para contribuir en ataque y defender sólidamente, puede hacerles la vida difícil a los extremos derechos rivales.","en":"After eight years of playing for clubs in Russia, Belgium, Greece and Turkey, Mohammadi – whose twin brother, Mehrdad, plays in Iran for Tractor – returned to the Iranian league in 2024 with Persepolis. However, playing for his childhood team did not go well for him and, after a decade as a regular with the national team, for a while he lost his place in the squad. That downturn coincided with the decision by the then Persepolis coach, former Bayern Munich striker Vahid Hashemian, to deploy him as a right-back, but after Hashemian’s departure Mohammadi was moved back to the left, where he rediscovered his form and with it his international place. Mohammadi may sometimes hesitate in key moments, but as a fast and combative left-back he can be a major asset when in top form. With his ability to contribute in attack as well as defend solidly, he can make life difficult for opposing right wingers."} },
  { number: 13, name: 'Hossein Kanaani-Zadegan', position: 'DF', age: 32, club: 'Persepolis', bio: {"es":"Kanaani-Zadegan, un defensor físicamente imponente, es conocido por aparecer en los titulares no solo por sus actuaciones sino también por sus francas entrevistas. Uno de esos momentos llegó cuando un mensaje de voz filtrado lo sorprendió invitando a una mujer no identificada a compartir un momento romántico con él en el autobús de la selección nacional. La reacción provocó su suspensión por dos partidos. Al igual que Shoja Khalilzadeh, perdió su puesto de titular después de que Carlos Queiroz regresara antes del Mundial de 2022, jugando solo 45 minutos contra Inglaterra. Tras la marcha de Quieroz, comentó en la publicación de despedida del técnico en Instagram: “Tú traicionaste a Irán, no a Shoja y a mí”. Más tarde, cuando Queiroz se hizo cargo de Qatar, Kanaani-Zadegan anotó dos goles en la victoria de Irán por 4-0, tomando lo que muchos vieron como una revancha. Reflexionando sobre su única aparición en el Mundial de 2022, dijo una vez: “Si Rashford hubiera jugado de mi lado, lo habría matado”.","en":"A physically imposing defender, Kanaani-Zadegan is known for making headlines not only with his performances but also with his outspoken interviews. One such moment came when a leaked voice message caught him inviting an unidentified woman to share a romantic moment with him on the national team bus. The backlash led to his suspension for two matches. Like Shoja Khalilzadeh, he lost his starting spot after Carlos Queiroz returned ahead of the 2022 World Cup, featuring for only 45 minutes against England. After Quieroz’s departure, he commented under the coach’s farewell post on Instagram: “You betrayed Iran, not me and Shoja.” Later, when Queiroz took charge of Qatar, Kanaani-Zadegan scored twice in Iran’s 4-0 victory, taking what many saw as revenge. Reflecting on his only appearance at the 2022 World Cup, he once said: “If Rashford had played on my side, I would have killed him.”"}, special: "Outspoken" },
  { number: 17, name: 'Aria Yousefi', position: 'DF', age: 24, club: 'Sepahan', bio: {"es":"Yousefi es uno de los tres laterales derechos de la plantilla de Irán, pero el último amistoso antes del anuncio de la plantilla final sugirió que Amir Ghalenooei podría utilizarlo en múltiples posiciones. En aquel partido contra Gambia, Yousefi empezó como lateral derecho, pero en la segunda parte pasó al centro del campo e incluso marcó un gol. Hablando de sus cambios posicionales y de jugar como extremo, dijo: \"Soy un jugador que, desde que tenía 18 años, he jugado en diferentes posiciones según las decisiones de los entrenadores. Ahora, con la aprobación del señor Ghalenooei y del cuerpo técnico, se me ha asignado una nueva posición. Dondequiera que el entrenador decida, es mi deber jugar\". Yousefi fue incluido en el equipo a pesar de no haber sido convocado para los amistosos de marzo con Irán. Sin embargo, después de que Danial Eiri no pudiera unirse al equipo debido a problemas de visa, Ghalenooei invitó a Yousefi y finalmente logró asegurar un lugar.","en":"Yousefi is one of three right-backs in Iran’s squad, but the last friendly before the announcement of the final squad suggested that Amir Ghalenooei may use him in multiple positions. In that match against Gambia, Yousefi started as a right-back, but in the second half he moved into midfield and even scored a goal. Speaking about his positional changes and playing as a winger, he said: “I am a player who, since I was 18, has played in different positions based on the coaches’ decisions. Now, with the approval of Mr Ghalenooei and the coaching staff, a new position has been assigned to me. Wherever the coach decides, it is my duty to play.” Yousefi was included in the squad despite not being called up for Iran’s March friendlies. However, after Danial Eiri was unable to join the team due to visa issues, Ghalenooei invited Yousefi, and he ultimately managed to secure a place."} },
  { number: 19, name: 'Ali Nemati', position: 'DF', age: 29, club: 'Foolad Khuzestan', bio: {"es":"Puede que Nemati no tenga muchas oportunidades de participar en la Copa del Mundo, pero el simple hecho de formar parte del equipo es un logro significativo para un jugador que estuvo a punto de dejar el fútbol a los 18 años. Estuvo a punto de perderse una prueba para los equipos juveniles de Irán debido a que llegó tarde y, poco después, un accidente de motocicleta lo dejó con un brazo y una clavícula rotos, lo que lo dejó fuera de juego durante un año entero. Sin embargo, logró volver al nivel más alto y consiguió su primera internacionalidad a los 29 años durante las eliminatorias para el Mundial de 2026. Fuera del campo, el polivalente defensor también ha mostrado un lado compasivo. Hace algún tiempo, ayudó a conseguir la liberación de personas encarceladas por deudas financieras pagando lo que debían.","en":"Nemati may not have many chances to feature at the World Cup but simply making the squad is a significant achievement for a player who came close to giving up football at 18. He nearly missed a trial for Iran’s youth teams due to arriving late and, not long after, a motorcycle accident left him with a broken arm and collarbone, sidelining him for an entire year. However, he worked his way back to the top level and earned his first cap at the age of 29 during the 2026 World Cup qualifiers. Off the pitch, the versatile defender has also shown a compassionate side. Some time ago, he helped secure the release of individuals imprisoned for financial debts by paying off what they owed."}, special: "Helping others" },
  { number: 23, name: 'Ramin Rezaeian', position: 'DF', age: 36, club: 'Foolad Khuzestan', bio: {"es":"Ningún jugador del fútbol iraní abraza el espectáculo como Rezaeian. Habiendo jugado para los tres clubes más importantes de Irán (Persépolis, Esteghlal y Sepahan), rara vez hace algo sin añadir un toque de estilo. Grabó su nombre en la historia del fútbol iraní en el Mundial de 2022 al marcar el segundo gol de Irán contra Gales. Aún así, a juzgar por su publicación fijada en Instagram, su encuentro con Cristiano Ronaldo en la Copa del Mundo 2018 parece tener un significado personal aún mayor. Hablando de ese partido en un programa de televisión, dijo: \"Me gusta mucho Ronaldo, y me pareció extraño jugar contra él. Jugué un poco con él... Incluso le dije: 'Si no te gusta, cambia de lado y ve a jugar allí'\". Rezaeian es un lateral derecho con mentalidad ofensiva, que a menudo deja espacio detrás de él para que los oponentes lo exploten.","en":"No player in Iranian football embraces showmanship quite like Rezaeian. Having played for all three of Iran’s biggest clubs – Persepolis, Esteghlal and Sepahan – he rarely does anything without adding a touch of flair. He etched his name into Iranian football history at the 2022 World Cup by scoring Iran’s second goal against Wales. Still, judging by his pinned Instagram post, his encounter with Cristiano Ronaldo at the 2018 World Cup appears to hold even greater personal significance. Speaking about that match on a TV show, he said: “I really like Ronaldo, and it felt strange to play against him. I messed around with him a bit … I even told him: ‘If you don’t like it, switch sides and go play over there.’” Rezaeian is an attack-minded right-back, which often leaves space behind him for opponents to exploit."}, special: "Showman" },
  { number: 25, name: 'Danial Eiri', position: 'DF', age: 22, club: 'Malavan', bio: {"es":"Eiri ha sido una de las estrellas emergentes del fútbol iraní durante las últimas temporadas y ya ha atraído un gran interés por parte de otros clubes. Es un fuerte defensor que es capaz de construir juego desde atrás y cuya habilidad aérea lo convierte en una amenaza en ambas áreas de penalti: anotó dos veces en un reciente partido de entrenamiento a puerta cerrada con la selección de Irán. El joven defensor ha tenido un desempeño tan bueno en la última temporada que Mehdi Pashazadeh, el ex defensa del Bayer Leverkusen que jugó para Irán en la Copa del Mundo de 1998, pidió públicamente no sólo que lo eligieran para la Copa del Mundo, sino también para ser titular. Después de una de las victorias de Copa de Malavan esta temporada, apareció un vídeo que mostraba a Iri bailando exuberantemente en el vestuario. Entonces, incluso si Eiri no tiene la oportunidad de jugar, en caso de que Irán gane cualquiera de sus partidos de la Copa del Mundo, aún puede mostrar sus habilidades fuera de la cancha.","en":"Eiri has been one of the breakout stars of Iranian football over the past couple of seasons and has already attracted significant interest from other clubs. He is a strong defender who is capable of building play from the back, and whose aerial ability makes him a threat in both penalty areas – he scored twice in a recent behind-closed-doors training match with the Iran squad. The young defender has performed so well in the recent season that Mehdi Pashazadeh, the former Bayer Leverkusen defender who played for Iran at the 1998 World Cup, publicly called for him not just to be picked for the World Cup, but to start. After one of Malavan’s cup victories this season, a video surfaced showing Iri dancing exuberantly in the dressing room. So even if Eiri does not get a chance to play, in the event of Iran winning any of their World Cup matches, he can still showcase his abilities off the pitch."} },
  // Volantes
  { number: 6, name: 'Saeid Ezatolahi', position: 'MF', age: 30, club: 'Shabab Al-Ahli', bio: {"es":"Si el gol de Ezatolahi contra España en el Mundial de 2018 no hubiera sido anulado por fuera de juego, se habría convertido en el autor de uno de los goles más importantes de la historia del fútbol iraní con tan solo 22 años. Pero la bandera se izó, y no fue la única decepción para un jugador alguna vez considerado como uno de los talentos más brillantes de su generación. Exatolahi fichó por el Atlético de Madrid con 17 años pero en lugar de alcanzar la cima del fútbol europeo ha tenido una carrera itinerante. En octubre de 2025, Ezatolahi fue capitán de la selección iraní por primera vez en un partido amistoso contra Tanzania. Después del partido, escribió en Instagram: \"He hecho un pacto conmigo mismo para luchar siempre por mis sueños, no temer a nadie y poner siempre el honor de Irán por encima de todo\". Ezatolahi, un mediocampista alto y elegante, combina tareas defensivas y creación de juego profunda con la voluntad de unirse a los ataques y contribuir con goles. Cuando fue descartado de la Copa Asiática AFC 2019 debido a una lesión, cantó una canción, Balatar, apoyando al equipo.","en":"If Ezatolahi’s goal against Spain at the 2018 World Cup had not been disallowed for offside, he would have become the scorer of one of the most important goals in Iranian football history at just 22 years old. But the flag went up, and it was not to be the only disappointment for a player once regarded as one of the brightest talents of his generation. Exatolahi joined Atlético Madrid at the age of 17 but instead of reaching the pinnacle of European football he has had an itinerant career. In October 2025, Ezatolahi captained the Iranian national team for the first time in a friendly match against Tanzania. Following the game, he wrote on Instagram:“I have made a pact with myself to always fight for my dreams, to fear no match, and to always put Iran’s honor above everything else.” A tall, elegant midfielder, Ezatolahi combines defensive duties and deep playmaking with a willingness to join attacks and contribute goals. When he was ruled out of the 2019 AFC Asian Cup due to injury he provided a rap to a song, Balatar, supporting the side."} },
  { number: 14, name: 'Saman Ghoddos', position: 'MF', age: 33, club: 'Al Ittihad Kalba', bio: {"es":"La década de Carlos Queiroz con Irán tuvo un impacto significativo en la selección nacional, y uno de sus legados duraderos es la integración de jugadores iraníes de doble nacionalidad o de segunda generación nacidos fuera del país. Uno de esos jugadores es Saman Ghoddos, nacido en Malmö, Suecia, de padres iraníes. Incluso representó a Suecia en dos partidos internacionales absolutos, pero cuando se dio cuenta de que no sería incluido en el equipo de Suecia para el Mundial de 2018, aceptó la invitación de Queiroz para jugar con Irán. Esta decisión marcó un punto de inflexión histórico. Uno de sus lanzamientos a balón parado contra Marruecos en la Copa del Mundo de 2018 derivó en un gol en propia meta, lo que ayudó a Irán a asegurar una de sus victorias más memorables en la historia de la Copa del Mundo. A nivel de clubes, Ghoddos se hizo un nombre en Östersund con Graham Potter, donde ayudó al club a ganar la Copa de Suecia y fue nombrado Delantero Sueco del Año. A medida que avanzaba su carrera, poco a poco fue ascendiendo a puestos más profundos. En Brentford con Thomas Frank, incluso jugó como lateral. Sin embargo, en la selección nacional, Ghoddos suele ser utilizado como un mediocampista central trabajador que contribuye en ataque, con un potente disparo de larga distancia.","en":"Carlos Queiroz’s decade-long spell with Iran had a significant impact on the national team, and one of his lasting legacies is the integration of dual-nationality or second-generation Iranian players born outside the country. One such player is Saman Ghoddos, born in Malmö, Sweden, to Iranian parents. He even represented Sweden in two full internationals but, when he realised he would not be included in Sweden’s 2018 World Cup squad, he accepted Queiroz’s invitation to play for Iran. This decision marked a historic turning point. One of his set-piece deliveries against Morocco in the 2018 World Cup led to an own goal, helping Iran secure one of its most memorable victories in World Cup history. At club level Ghoddos made his name at Östersund under Graham Potter, where he helped the club win the Swedish Cup and was named Swedish Forward of the Year. As his career progressed, he gradually moved into deeper positions. At Brentford under Thomas Frank, he was even deployed as a full-back. For the national team, however, Ghoddos is typically used as a hard-working central midfielder who contributes in attack, with a powerful long-range shot."} },
  { number: 15, name: 'Rouzbeh Cheshmi', position: 'MF', age: 32, club: 'Esteghlal', bio: {"es":"Con una altura de 1,94 m, este mediocampista defensivo es mejor conocido por su mirada severa y sus cejas fruncidas, a menos que menciones el momento más inolvidable de su carrera: su impresionante gol contra Gales en la Copa del Mundo 2022, un espectacular disparo de larga distancia desde fuera del área penal. \"Ni siquiera disparo en PlayStation\", dijo Cheshmi. \"Pero cuando me llegó el balón, no pude escuchar nada, ni el estadio, ni siquiera mis compañeros pidiendo un pase. Fue verdaderamente obra de Dios\". Ex capitán de la selección iraní sub-23, también es capaz de jugar como central. Contra Inglaterra, también en 2022, estuvo en el corazón de la defensa iraní de cinco hombres, pero tuvo una mala actuación: “Sí, fui responsable de dos goles”, admitió. Ya sea que tenga otra noche difícil o que marque otro gol decisivo en el Mundial de 2026, Cheshmi ahora tiene razones aún más importantes para sonreír: sus gemelos, Salman y Mila, que nacieron unos meses después del Mundial de Qatar.","en":"Standing 1.94m tall, this defensive midfielder is best known for his stern look and furrowed eyebrows – unless you mention the most unforgettable moment of his career: his stunning goal against Wales at the 2022 World Cup, a spectacular long-range strike from outside the penalty area. “I don’t even shoot in PlayStation,” Cheshmi said. “But when the ball came to me, I couldn’t hear anything – not the stadium, not even my teammates asking for a pass. It was truly God’s work.” A former captain of Iran’s Under-23 team, he is also capable of playing as a centre-back. Against England, also in 2022, he was placed in the heart of Iran’s five-man defense but delivered a poor performance: “Yes, I was responsible for two goals,” he admitted. Whether he has another difficult night or scores another decisive goal at the 2026 World Cup, Cheshmi now has even more important reasons to smile: his twins, Salman and Mila, who were born a few months after the Qatar World Cup."} },
  { number: 21, name: 'Mohammad Ghorbani', position: 'MF', age: 24, club: 'Al Wahda', bio: {"es":"Ghorbani formó parte de los campamentos de la selección nacional de Irán en la preparación para la Copa del Mundo de 2022, pero no formó parte del equipo final. Sin embargo, en los últimos cuatro años, con la experiencia adquirida en las ligas rusa y emiratí, se ha convertido en una presencia habitual en la configuración del equipo nacional, y nunca hubo dudas de que Amir Ghalenoei lo elegiría en su equipo final, incluso si su lugar en el once inicial no está seguro. Ghorbani es uno de esos jugadores polivalentes que a lo largo de su carrera ha jugado en múltiples posiciones, incluyendo lateral izquierdo, central e incluso detrás del delantero, pero en la selección nacional juega sólo como centrocampista defensivo. Como muchos miembros del equipo, Ghorbani ha hablado de su optimismo sobre las posibilidades de Irán de pasar de la fase de grupos. Después del empate, dijo que Irán podría vencer a Nueva Zelanda 1-0 o 2-0, lograr al menos un empate contra Bélgica y Egipto y clasificarse para la siguiente ronda.","en":"Ghorbani was part of Iran’s national team camps in the build-up to the 2022 World Cup but did not make the final squad. However, over the past four years, with experience gained in the Russian and Emirati leagues, he has become a regular presence in the national team setup, and there was never any doubt that Amir Ghalenoei would pick him in his final squad, even if his place in the starting XI is not secure. Ghorbani is one of those versatile players who over his career has featured in multiple positions, including left-back, centre-back, and even behind the striker, but in the national team he plays only as a defensive midfielder. Like many members of the squad, Ghorbani has spoken of his optimism about Iran’s chances of progressing beyond the group stage. After the draw, he said Iran could beat New Zealand 1-0 or 2-0, take at least a draw against Belgium and Egypt, and qualify for the next round."} },
  { number: 26, name: 'Amirmohammad Razzaghinia', position: 'MF', age: 19, club: 'Esteghlal', bio: {"es":"El integrante más joven de la selección de Irán en este Mundial es un joven centrocampista que, después de jugar en las selecciones Sub-16, Sub-17, Sub-20 y Sub-23, ha tenido actuaciones sobresalientes en la liga iraní durante las dos últimas temporadas y logró ganarse su lugar en la selección absoluta con sólo 20 años. Debutó con pleno derecho contra Corea del Norte el pasado mes de junio y prefiere jugar como centrocampista defensivo, aunque si tiene visión de portería también tiene Un disparo potente y peligroso. En una de sus pocas entrevistas televisivas, celebrada unos días antes del anuncio del equipo final para la Copa del Mundo, Razzaghinia no pudo responder las preguntas del presentador sobre las apariciones anteriores de Irán en la Copa del Mundo, y el clip rápidamente se volvió viral en las redes sociales. En esa misma entrevista, dijo: \"El partido contra Nueva Zelanda es nuestro partido más difícil porque es el primer partido. Definitivamente debemos ganar este partido, y después pensaremos en los siguientes partidos\".","en":"The youngest member of Iran’s national team at this World Cup is a young midfielder who, after playing for the Under-16, Under-17, Under-20, and Under-23 teams, has delivered outstanding performances in the Iranian league over the past two seasons and was able to earn his place in the senior international side at the age of just 20. He made his full debut against North Korea last June and prefers to play as a defensive midfielder, though if he gets within sight of goal he also has a powerful and dangerous shot. In one of his few TV interviews, held a few days before the announcement of the final World Cup squad, Razzaghinia was unable to answer the host’s quiz questions about Iran’s previous World Cup appearances, the clip quickly going viral on social media. In that same interview, he said: “The match against New Zealand is our hardest game because it is the first match. We must definitely win this game, and after that we will think about the following matches.”"}, special: "Future star" },
  // Delanteros
  { number: 7, name: 'Alireza Jahanbakhsh', position: 'FW', age: 32, club: 'Dender', bio: {"es":"Jahanbakhsh es una de las pocas estrellas iraníes que nunca ha jugado en ninguno de los dos grandes clubes de Teherán, Persépolis o Esteghlal. A la edad de 19 años rechazó Persépolis y se mudó a los Países Bajos con NEC Nijmegen. Esa decisión explica en parte su popularidad relativamente mixta entre algunos aficionados al fútbol en Irán. Jahanbakhsh es de la provincia de Gilan, en el norte de Irán, una región cuya gente suele ser estereotipada por tener rasgos faciales prominentes. Durante su estancia en Brighton, estuvo involucrado en un enfrentamiento con el defensa del Manchester City Kyle Walker. Reflexionando sobre el incidente, dijo: \"Me tocó y me golpeó la nariz. Soy del norte de Irán y tenemos narices grandes. ¡Es difícil pasarlo por alto!\". A sus 32 años, Jahanbakhsh es más un suplente de impacto que un titular determinado, habiendo perdido parte del ritmo explosivo que mostró durante sus mejores años en Alkmaar, entre 2015 y 2018, cuando sus carreras incisivas y sus espectaculares goles de larga distancia lo convirtieron en uno de los jugadores más temidos de la Eredivisie.","en":"Jahanbakhsh is one of the few Iranian stars who has never played for either of Tehran’s two major clubs, Persepolis or Esteghlal. At the age of 19 he turned Persepolis down in favour of moving to the Netherlands with NEC Nijmegen. That decision partly explains his relatively mixed popularity among some football fans in Iran. Jahanbakhsh is from Gilan Province in northern Iran, a region whose people are often stereotyped for having prominent facial features. During his time at Brighton, he was involved in a confrontation with Manchester City defender Kyle Walker. Reflecting on the incident, he said: “He touched me and hit my nose. I’m from the north of Iran, and we have big noses – it’s hard to miss!” At 32, Jahanbakhsh is more of an impact sub than a certain starter, having lost some of the explosive pace he displayed during his peak years at Alkmaar, between 2015 and 2018, when his incisive runs and spectacular long-range goals made him one of the Eredivisie’s most feared players."}, special: "Well-travelled" },
  { number: 8, name: 'Mohammad Mohebi', position: 'FW', age: 27, club: 'Rostov', bio: {"es":"Mohebi puede considerarse uno de los extremos más singulares (y al mismo tiempo uno de los más desafortunados) de este equipo. Es un jugador que, si ciertos momentos de su trayectoria futbolística se hubieran desarrollado de manera diferente, podría tener muchas más apariciones internacionales a su nombre. Aun así, sus estadísticas en un número limitado de partidos son impresionantes: 34 partidos internacionales, 13 goles y nueve asistencias, lo que significa participación directa en 22 goles en el momento de escribir este artículo. Para un extremo, especialmente a nivel de selecciones nacionales, se trata de un retorno notable. Mohebi fue convocado por primera vez a la selección nacional en 2019 y disfrutó de un debut de ensueño contra Camboya al anotar dos goles y una asistencia, pero después de jugar tres veces en apenas unas semanas no volvió a jugar durante más de tres años. Mohebi es amigo de la infancia del izquierdista Mehdi Ghayedi, un nativo de la ciudad costera de Bushehr, y la presencia simultánea de los dos en la alineación puede ser particularmente emocionante de ver.","en":"Mohebi can be considered one of the most unique – and at the same time one of the unluckiest – wingers in this squad. He is a player who, had certain moments in his football journey unfolded differently, might have far more international appearances to his name. Even so, his statistics in a limited number of matches are impressive: 34 international caps, 13 goals, and nine assists, meaning direct involvement in 22 goals at the time of writing. For a winger, especially at national-team level, that is a remarkable return. Mohebi was first called up to the national team in 2019, and enjoyed a dream debut against Cambodia by recording two goals and one assist, but after playing three times in just a few weeks he did not feature again for more than three years. Mohebi is the childhood friend of left-winger Mehdi Ghayedi, a fellow native of the coastal city of Bushehr, and the simultaneous presence of the two in the lineup can be particularly exciting to watch."} },
  { number: 9, name: 'Mehdi Taremi', position: 'FW', age: 33, club: 'Olympiakos', captain: true, bio: {"es":"Durante años, parecía que Mehdi Taremi sería más conocido por sus travesuras fuera del campo (una suspensión global del fútbol de cuatro meses relacionada con una disputa contractual con el club turco Rizespor, una relación con la famosa actriz iraní Sahar Ghoreyshi) que por cualquier cosa que pudiera hacer en el campo. Pero su paso al club portugués Rio Ave en 2019 lo cambió todo y luego se fue al Porto y al Inter, donde pudo mostrar plenamente sus habilidades. Ganó ligas y copas con el Oporto y llegó a la final de la Liga de Campeones con el Inter, mientras que su espectacular chilena con el Oporto contra el Chelsea fue nominado al Premio Puskás y elegido Gol de la Temporada en la Liga de Campeones. Taremi es un delantero que destaca corriendo detrás de las líneas defensivas, e incluso un contacto mínimo suele ser suficiente para caer y ganar penales, una característica que le ha valido una reputación controvertida en Portugal. Es el capitán y la estrella de Irán. Con dos goles ante Inglaterra en el Mundial de 2022, ya es el máximo goleador histórico de Irán en el torneo.","en":"For years, it looked like Mehdi Taremi would be better known for off-field shenanigans – a four-month global ban from football related to a contract dispute with Turkish club Rizespor, a relationship with the famous Iranian actress Sahar Ghoreyshi – than for anything he might do on the pitch. But his move to Portuguese club Rio Ave in 2019 changed everything, and he later went to Porto and Inter, where he was able to fully showcase his abilities. He won league and cup titles with Porto and reached the Champions League final with Inter, while his spectacular bicycle kick for Porto against Chelsea was nominated for the Puskás Award and voted Goal of the Season in the Champions League. Taremi is a striker who excels at running behind defensive lines, and even minimal contact is often enough for him to go down and win penalties – a trait that has earned him a controversial reputation in Portugal. He is Iran’s captain and star. With two goals against England in the 2022 World Cup, he is already Iran’s all-time top scorer in the tournament."}, special: "Inspiration" },
  { number: 10, name: 'Mehdi Ghaedi', position: 'FW', age: 28, club: 'Al Nassr', bio: {"es":"Poco después de que Ghaedi se uniera al Esteghlal en julio de 2017, se convirtió en uno de los jugadores más jóvenes en la historia de la Pro League de Irán, pero rápidamente quedó claro que su camino hacia la cima no iba a ser fácil: en enero siguiente, conduciendo a alta velocidad, su coche se salió de la carretera y se estrelló, provocando la muerte de un amigo y enviándolo a cuidados intensivos. Desde entonces, una combinación de lesiones y problemas fuera del campo han limitado las apariciones internacionales de un jugador conocido con el sobrenombre de Bashu, en honor a un famoso personaje cinematográfico iraní. Ghaedi mide 1,66 m, por lo que su amigo de la infancia y ocasional internacional iraní Mohammad Mohebi tiene la siguiente explicación: “Si no me equivoco, teníamos 12 o 13 años jugando en categorías inferiores”, recordó. \"Le pasé un pase en profundidad, se fue uno contra uno, dribló al portero, pero el portero le cometió una falta golpeándole el tobillo. Fue entonces cuando Mehdi se rompió el tobillo y eso afectó su crecimiento. Por eso dejó de crecer y se quedó bajo\". A pesar de esto, Ghaedi sigue siendo un extremo capaz de cambiar los partidos en su día con su combinación de técnica y ritmo explosivo.","en":"Soon after Ghaedi joined Esteghlal in July 2017 he became one of the youngest players in the history of Iran’s Pro League, but it quickly became clear that his path to the top was not going to be smooth: the following January, driving at high speed, his car veered off the road and crashed, causing the death of a friend and sending him to intensive care. Since then a combination of injuries and off-field issues have limited the international appearances of a player known by the nickname Bashu, after a famous Iranian film character. Ghaedi is 1.66m tall, for which his childhood friend and occasional Iran international Mohammad Mohebi has the following explanation: “If I’m not mistaken, we were 12 or 13 years old playing at youth level,” he remembered. “I played a through ball to him, he went one-on-one, dribbled the goalkeeper, but the keeper fouled him by hitting his ankle. That’s when Mehdi broke his ankle, and it affected his growth. That’s why he stopped growing and remained short.” Despite this, Ghaedi remains a winger capable of changing games on his day with his combination of technique and explosive pace."}, special: "Game-changer" },
  { number: 11, name: 'Ali Alipour', position: 'FW', age: 30, club: 'Persepolis', bio: {"es":"Alipour, ex máximo goleador de la liga Pro League del Golfo Pérsico de Irán, ha pasado la mayor parte de su carrera en dos períodos en Persépolis, interrumpidos por cuatro años en Portugal con Maritimo y Gil Vicente. Ha sido un goleador constante, sobre todo mientras jugaba en Irán, pero las fluctuaciones en su forma le han impedido asegurarse un lugar permanente en la selección nacional, y más de ocho años después de su debut sólo tiene una docena de apariciones, la mayoría de ellas en el último año. Sin embargo, la controvertida omisión de Sardar Azmoun para esta Copa del Mundo creó una oportunidad para que Alipour se abriera paso en el equipo final. Puede que no tenga mucho tiempo de juego, pero ya ha estado pensando en la celebración de su gol: \"En los partidos internacionales, no es posible revelar nada debajo de la camiseta, pero si se me permitiera, definitivamente mostraría la bandera de mi país, Irán. Y si Dios quiere, si tengo la oportunidad y puedo ser uno de los soldados de mi país, besaré la insignia iraní después de marcar\".","en":"A previous top scorer in Iran’s Persian Gulf Pro League league, Alipour has spent most of his career in two spells at Persepolis, interrupted by four years in Portugal with Maritimo and Gil Vicente. He has been a consistent goalscorer, particularly while playing in Iran, but fluctuations in form have prevented him from securing a permanent place in the national team, and more than eight years after his debut he has only a dozen appearances, most of them in the last year. However, the controversial omission of Sardar Azmoun for this World Cup created an opportunity for Alipour to push his way into the final squad. He may not get much playing time, but he has already been thinking about his goal celebration: “In international matches, it’s not possible to reveal anything under the shirt, but if it were allowed, I would definitely display the flag of my country, Iran. And God willing, if I get the chance and can be one of my country’s soldiers, I will kiss the Iranian badge after scoring.”"} },
  { number: 16, name: 'Mehdi Torabi', position: 'FW', age: 31, club: 'Tractor', bio: {"es":"Torabi estuvo en el equipo de Irán para la Copa del Mundo en 2018, pero nunca llegó a la cancha, y cuatro años después regresó al equipo y al banquillo, aunque esta vez fue utilizado por Carlos Queiroz en los tres partidos. Sin embargo, hasta hace poco, sus posibilidades de formar parte del equipo para la Copa del Mundo 2026 parecían extremadamente escasas. Pero Amir Ghalenoei lo nombró en su equipo, casi dos años después de la última aparición internacional de Torabi. Es uno de los pocos futbolistas iraníes que expresa abiertamente sus creencias religiosas y políticas. Es famoso por celebrar un gol con Persépolis en 2019 levantándose la camiseta para revelar el mensaje: “La única manera de salvar el país = obediencia al Líder Supremo”, causando una considerable controversia. “Esta celebración fue enteramente idea mía y pueden estar seguros de que nadie me instruyó para hacerlo ni me influyó desde ningún lugar”, dijo. “Antes de decidirme por esta celebración lo había pensado todo y sabía que habría reacciones tanto positivas como negativas”.","en":"Torabi was in Iran’s World Cup squad in 2018 but never made it onto the pitch, and four years later was back in the squad and back on the bench, though this time he was used by Carlos Queiroz in all three matches. However, until recently, his chances of making the 2026 World Cup squad seemed extremely slim. But Amir Ghalenoei named him in his squad, nearly two years after Torabi’s last international appearance. He is one of the few Iranian footballers who openly expresses his religious and political beliefs. He famously celebrated a goal for Persepolis in 2019 by lifting his shirt to reveal the message: “The only way to save the country = obedience to the Supreme Leader”, causing considerable controversy. “This celebration was entirely my own idea, and you can be sure that no one instructed me to do it or influenced me from anywhere,” he said. “Before deciding on this celebration I had thought everything through and knew there would be both positive and negative reactions.”"} },
  { number: 18, name: 'Amirhossein Hosseinzadeh', position: 'FW', age: 25, club: 'Tractor', bio: {"es":"Hosseinzadeh ha sido el mejor jugador de la liga iraní durante las dos últimas temporadas. En 2024-25 terminó como máximo goleador de la liga con 14 goles y jugó un papel clave en el primer título de liga de Tractor. Esta temporada lideraba la tabla de goleadores cuando el estallido de la guerra obligó a una pausa en la competición. Durante el año pasado, también marcó cinco goles con la selección nacional, lo que demuestra que está preparado para brillar en escenarios más importantes. Considerado como una de las principales esperanzas ofensivas de Irán para la Copa del Mundo, cree que el equipo puede progresar hasta el final del torneo: \"Exactamente desde el día en que se anunció el sorteo de la Copa del Mundo, el entrenador Ghalenoei nos dijo que nuestro objetivo debe ser salir del grupo, y no sólo una ronda, sino que debemos apuntar a ir aún más lejos, dos etapas más allá. Todos los jugadores han jurado juntos que, si Dios quiere, esta vez avanzaremos del grupo y daremos una sorpresa\".","en":"Hosseinzadeh has been the best player in the Iranian league over the past two seasons. In 2024-25 he finished as the top scorer in the league with 14 goals and played a key role in Tractor’s first-ever league title. This season he was leading the scoring charts when the outbreak of war forced a pause in competition. Over the past year, he has also scored five goals for the national team, showing that he is ready to shine on bigger stages. Regarded as one of Iran’s main attacking hopes for the World Cup, he believes the team can progress deep into the tournament: “Exactly from the day the World Cup draw was announced, Coach Ghalenoei told us that our goal must be to get out of the group – and not just one round, but we should aim to go even further, two stages beyond that. All the players have sworn together that, God willing, we will advance from the group this time and create a surprise.”"}, special: "In-form goalscorer" },
  { number: 20, name: 'Shahriar Moghanloo', position: 'FW', age: 31, club: 'Kalba', bio: {"es":"Moghanloo es el miembro más inusual del equipo iraní para el Mundial de 2026. No estaba incluido en la lista inicial de 30 hombres de Amir Ghalenooei. Sin embargo, tras la lesión de Roozbeh Cheshmi, lo convocaron como sustituto y, al final, aunque Cheshmi no abandonó, Moghanloo permaneció en el equipo final. Es un delantero alto y Ghalenooei probablemente lo utilizará en los minutos finales, especialmente cuando el equipo depende de los centros desde las bandas para atacar. Hace dos temporadas, fue el máximo goleador de la liga iraní, pero aún no ha replicado esa brillantez en Kalba. Aun así, la ausencia de una fuerte amenaza aérea en el equipo inicial explica la selección de Ghalenooei. Moghanloo es de Zanjan, una ciudad famosa por sus cuchillos afilados. Para ganar tiempo de juego en la Copa del Mundo, tendrá que ser tan afilado como los cuchillos de su ciudad natal.","en":"Moghanloo is the most unusual squad member from Iran to the 2026 World Cup. He was not included in Amir Ghalenooei’s initial 30-man list. However, after Roozbeh Cheshmi’s injury scare, he was called up as a replacement – and in the end, even though Cheshmi did not drop out, Moghanloo remained in the final squad. He is a tall striker, and Ghalenooei will probably use him in the final minutes, especially when the team relies on crosses from the wings to attack. Two seasons ago, he was the top scorer in the Iranian league, but he is yet to replicate that brilliance at Kalba. Still, the absence of a strong aerial threat in the initial squad explains Ghalenooei’s selection. Moghanloo is from Zanjan, a city famous for its sharp knives. To earn playing time at the World Cup, he will need to be as sharp as the knives from his hometown."}, special: "Shock call-up" },
  { number: 24, name: 'Dennis-Yerai Eckert Ayensa', position: 'FW', age: 28, club: 'Standard Liège', bio: {"es":"Eckert es el quinto germano-iraní convocado por Irán, pero el primero cuyos vínculos con el país no se remontan a los padres sino a los abuelos: su madre es española, su padre alemán, pero su abuelo paterno nació en Irán y la famosa actriz iraní Anahita Dargahi es tía. “Mi tía Anahita me apoya en todo”, dijo en Instagram. \"Estoy orgulloso de tener una tía tan increíble\". Eckert, ex internacional alemán sub-19, fue vinculado por primera vez con Irán en septiembre pasado. \"Mi padre es mitad iraní pero no tiene pasaporte. Mi abuelo es iraní, pero está muerto. Eso dificulta las cosas\", dijo. \"Ni siquiera sabría por dónde empezar a solicitar la ciudadanía\". Pero en marzo tenía doble nacionalidad y una convocatoria internacional (aunque no tenía autorización de la FIFA y no podía jugar) y a principios de mayo se le expidió el pasaporte. A sus 29 años, y como delantero que ha alcanzado cifras dobles de goles en la liga sólo una vez, con el Ingolstadt en la tercera división alemana hace seis temporadas, es una presencia improbable pero intrigante en la Copa del Mundo.","en":"Eckert is the fifth German-Iranian to be called up by Iran, but the first whose links with the country go back not to parents but to grandparents: his mother is Spanish, his father German, but his paternal grandfather was born in Iran and the famous Iranian actress Anahita Dargahi is an aunt. “My aunt Anahita supports me in everything,” he said on Instagram. “I’m proud to have such an amazing aunt.” A former Germany Under-19 international, Eckert was first linked with Iran only last September. “My father is half Iranian but he doesn’t have a passport. My grandfather is Iranian, but he’s dead. So that makes things difficult,” he said. “I wouldn’t even know where to start to apply for citizenship.” But by March he had dual nationality and an international call-up – though not clearance from Fifa, and he was unable to play – and in early May his passport was issued. At 29, and as a striker who has reached double figures for league goals only once, for Ingolstadt in the German third division six seasons ago, he is an unlikely but intriguing presence at the World Cup."} },
];

export const lineup = {
  formation: '4-2-3-1',
  startingXI: [1, 2, 4, 13, 5, 6, 14, 7, 10, 8, 9]
};
